messages.content:
Tool response:
Tool: get_maintenance_schedule_details
Description: Get Maintenance Schedule Details
Parameters:
    {
      "type": "object",
      "properties": {
        "asset_tag": {
          "type": "string",
          "description": "Unique identifier for the equipment",
          "title": "Asset Tag"
        },
        "schedule_type": {
          "type": "string",
          "description": "Type of maintenance schedule",
          "title": "Schedule Type"
        }
      },
      "required": [
        "asset_tag",
        "schedule_type"
      ]
    }

Tool response:
Tool: adjust_maintenance_schedule
Description: Adjust Maintenance Schedule
Parameters:
    {
      "type": "object",
      "properties": {
        "asset_tag": {
          "type": "string",
          "description": "Unique identifier for the equipment",
          "title": "Asset Tag"
        },
        "schedule_type": {
          "type": "string",
          "description": "Type of maintenance schedule",
          "title": "Schedule Type"
        },
        "days_shifted": {
          "type": "integer",
          "title": "Days Shifted",
          "description": "Number of days to shift the schedule forward (positive integer)"
        },
        "reason": {
          "type": "string",
          "title": "Reason",
          "description": "Reason for the adjustment"
        },
        "approved_by": {
          "type": "string",
          "title": "Approved By",
          "description": "Name or identifier of approver"
        }
      },
      "required": [
        "asset_tag",
        "schedule_type",
        "days_shifted",
        "reason",
        "approved_by"
      ]
    }
